#!/usr/bin/env python3
# reserve_L22e.py — 새 과 L22e(박람회장 정원의 그루터기와 화단 · 세계 s22 의 e) — 캠벨 35장(구조 · 생장) · 36장(물 포텐셜 · 뿌리압) · 37장(흙 · 필수 원소 · 특수 영양).
#  「박람회 정원의 늙은 거목을 베어 낸 아침」 한 장면(Gemini 가 통째로 그림 + 구역 편집 16 + PIL 둘 — L22e_build.sh).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-16 새 과 L22e]'
new = {
 '커다란 잎 모자를 쓴 일꾼이 줄로 내려 주는 입 묶은 갈색 자루 + 그 자루를 받아 안는 몸이 뿌리로 된 사람(머리에 잎 하나) + 흙 속에서 바구니(물병 · 칼 · 자갈 · 빨간 머리 성냥)를 머리에 인 뿌리 다리 꼬마': f'줄기계(잎 = 빛 · CO₂ → 당)와 뿌리계(물 · 무기물)가 서로 기댐 전용 {B} — L22e s2. 갈색 자루 = 당(L22c) · 물병 = H₂O · 칼 = K⁺ · 자갈 = Ca²⁺ · 성냥 = 인. ⚠ 「사람이 멘 자루」(배수성)와 다르다 — 줄에 매달거나 안아 받는 자루.',
 '대나무처럼 마디 진 초록 새싹 — 잎겨드랑이마다 반쯤 감긴 졸린 눈 · 꼭대기에 크게 뜬 눈 하나': f'줄기의 마디 · 마디사이 · 정단눈(꼭대기 · 깨어 있음) · 곁눈(잎겨드랑이 · 잠듦 = 정단우세) 전용 {B} — L22e s3. 눈(目) = 눈(芽). ⚠ 다른 판의 식물에 눈알을 달지 마라 — 이 새싹의 뜻이 흐려진다.',
 '통나무만 한 김밥의 단면 — 겉의 검은 김 · 하얀 밥 · 고리로 둘러 박힌 초록 오이(안) · 분홍 햄(밖) 짝 · 고리 안 가운데 밥': f'3대 조직계(김 = 표피 · 오이 + 햄 짝 = 관다발(물관부 안 · 체관부 밖) · 밥 = 기본조직(고리 안 = 속 · 고리 밖 = 피층)) · 쌍떡잎 어린 줄기의 고리 배열 전용 {B} — L22e s4. ⚠ 김 한 장 · 김밥을 다른 판에서 음식으로 쓰지 마라. ⚠ 오이는 【궤짝의 사과 · 오이 · 공】(P450)과 가른다 — 썬 단면의 속재료.',
 '새싹 곁에 세운 키 재기 막대 / 그루터기 허리에 감은 노란 줄자': f'1차 생장(정단분열조직 · 길이 · 모든 식물) / 2차 생장(측생분열조직 · 굵기) 전용 {B} — L22e s5. ⚠ 【노란 줄자를 감은 물고기 뼈 화석 돌판】(형태종 L35c)과 가른다 — 이쪽은 살아 있는 그루터기의 허리.',
 '그루터기 단면 가장자리의 초록 고리 위 초록 모자 꼬마 일꾼들 — 고리 안쪽엔 청록 관 토막 · 바깥쪽엔 분홍 관 토막': f'관다발형성층 → 안쪽 2차 물관부(목재) · 바깥쪽 2차 체관부 전용 {B} — L22e s6. 청록 관 = 물관 · 분홍 관 = 체관(L22b · L22c). Gemini 가 두 번 섞어 그려 `L22e_tubes.py` 가 빛깔을 자리대로 바꿨다(고리 타원 안 = 청록 · 밖 = 분홍). ⚠ 다른 판에서 청록 · 분홍 토막을 한 줄에 섞어 두지 마라.',
 '그루터기에 무릎 꿇고 돋보기로 테를 세는 줄무늬 재킷의 심판(넥타이 없음) + 연한 띠 · 짙은 띠가 번갈아 두른 단면': f'나이테 = 봄재(세포 크고 벽 얇음 · 연함 · 물 수송) + 여름재(작고 벽 두꺼움 · 짙음 · 지지) 전용 {B} — L22e s7. 돋보기 = 들여다봄(L52a 와 같은 뜻 줄기 — 배율 ≠ 분해능은 L52a 몫).',
 '벌목꾼이 외투처럼 통째로 벗겨 든 껍질(안감 분홍 · 겉 거친 갈색) · 그 밑의 청록 나무 / 그루터기 옆구리를 타고 오르며 갈색 코르크 조각을 던지는 주황 모자 일꾼들': f'수피 = 관다발형성층 바깥 전부(2차 체관부 = 분홍 안감 + 주피) · 껍질은 형성층에서 벗겨진다 / 코르크형성층 → 코르크(표피 대체) · 주피 전용 {B} — L22e s8. ⚠ 코르크 마개(코르티솔) · 코르크 판자(수베린 L22b)와 가른다 — 이쪽은 껍질 조각.',
 '은빛 재봉 골무를 쓴 곧은 뿌리 끝 — 골무 위 둘로 갈라지는 작은 세포 → 길게 늘어난 세포 → 짧고 곧은 흰 털 솔': f'뿌리골무(분열조직 보호) · 분열대 → 신장대 → 성숙대 · 뿌리털(표피세포 돌출 · 흡수 면적) 전용 {B} — L22e s9. 털은 갈라지지 않는다 — 갈라진 흰 선은 곁뿌리로 읽혀 Gemini 구역 편집 ZQ 로 털 솔로 바꿨다. ⚠ 은빛 골무를 다른 판의 손가락 · 바늘과 함께 쓰지 마라.',
 '세로로 가른 굵은 뿌리 — 가운데 청록 · 분홍 관 다발 · 그 둘레 검은 안감 · 속에서 돋아 바깥 벽을 금 가게 하며 뚫고 나오는 갈색 곁뿌리': f'곁뿌리는 내초에서 돋아 내피 · 피층을 뚫고 나온다(겉에서 돋지 않음) 전용 {B} — L22e s10. 검은 안감 = 내피(L22b 의 검은 가스 파이프 고리).',
 '분수대 연못에 선 판자 물통(사과 · 포도 더미) — 분수 물방울이 통 속으로 떨어지고 판자 벽이 술통처럼 불룩해 떨린다': f'물 포텐셜 Ψ = Ψs + Ψp(물은 Ψ 높은 곳 → 낮은 곳 · 순수한 물 0 · 용질이 Ψs 를 낮춤 · 판자 벽이 되밂 = 압력 포텐셜) 전용 {B} — L22e s11. 판자 벽 = 세포벽 · 팽압(L53b) · 사과 · 포도 = 용질(L53b 삼투). ⚠ 유리 수조 · 나무 궤짝 · 둥근 통 더미와 가른다.',
 '화단 위 딸기 잎마다 맺힌 맑은 물방울 + 흙 속에서 두 손을 치켜들고 진땀 흘리며 밀어 올리는 꼬마(곁에 위로 향한 파란 화살 둘)': f'뿌리압(밤 · 약함 — 몇 m) · 일액현상(잎 끝 물방울) 전용 {B} — L22e s12. 밀어 올림 = 뿌리압 ↔ 위에서 당기는 밧줄 = 응집-장력(L22b s7).',
 '유리 너머 흙 — 위 썩은 잎이 섞인 검고 푸석한 흙 · 가운데 갈색 흙 · 아래 굵은 모래 · 자갈 + 납작한 회색 점토 조각 위의 자갈 · 은빛 구슬 + 뿌리털이 뿌린 맑은 물에 떨어져 나와 날아가는 칼': f'양토(모래 · 미사 · 점토) · 부식질 · 양이온 교환(음전하 점토 · 부식질이 K⁺ · Ca²⁺ · Mg²⁺ 를 붙듦 → 뿌리가 내놓은 H⁺ 가 바꿔치기) 전용 {B} — L22e s13. 맑은 물 = H⁺ · 칼 = K⁺ · 자갈 = Ca²⁺ · 은빛 구슬 = Mg. ⚠ 「－」 표는 그리지 않았다(글자 · 기호 없음 — 음전하는 말로).',
 '초록 앞치마 정원 의사의 작업대 — 맑은 물에 뿌리를 담근 유리병 화초 셋(왼쪽 하나만 시듦) + 분수대 곁 선반 윗칸의 큰 갈색 병 아홉 · 아랫칸 작은 스포이트 병 여덟': f'수경재배(원소 하나씩 빼고 길러 시들면 필수) · 필수 원소 17 = 다량 9 + 미량 8(주로 효소 보조인자) 전용 {B} — L22e s14. 병 개수가 곧 수. ⚠ 줄무늬 파라솔은 그리지 않는다(【펴 든 파라솔】 = 파라믹소 — 처음 바탕의 파라솔 둘을 ZI · ZJ 로 지웠다) · 정원사 · 물뿌리개(L46d · L51a · 흡수영양)와 가른다 — 병을 든 「정원 의사」.',
 '작업대 앞 끝에 넘어진 빈 병 셋(가장 큰 호박색 병 · 빨간 머리 성냥이 꽂힌 병 · 칼날이 꽂힌 병) + 아래 잎부터 누런 화분': f'생장 · 수확량에 가장 크게 기여 = 질소 · 가장 흔한 결핍 = 질소 · 인 · 칼륨(N · P · K) · 이동성 원소 결핍은 늙은 잎부터 전용 {B} — L22e s15. 호박색 = 질산(L22d) · 성냥 = 인 · 칼 = K⁺.',
 '쓰러진 거목 가지의 식객들 — 흰 열매 달린 둥근 초록 잎 뭉치(태연) · 가지에 감겨 축 늘어진 채 부스러기가 떨어지는 가는 주황 실 덩굴 · 빗물을 받는 분홍 난초 · 뾰족 잎 브로멜리아드 + 맨 오른쪽 아래 화분의 파리지옥과 파리': f'겨우살이(반기생 · 제 잎으로 광합성) · 새삼(전기생 · 엽록소 없음 — 숙주가 쓰러지자 말라 감) · 착생식물(붙어 살 뿐 빼앗지 않음) · 식충식물(질소 보충 · 광합성은 함) 전용 {B} — L22e s16. ⚠ 【털이 돋은 빨대】(스트라메노파일) · 국수와 가른다 — 새삼은 가는 주황 실.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('펴 든 파라솔', f'★ {B} 「작업대는 파라솔 아래」 설계가 이 예약을 놓쳐 처음 바탕에 줄무늬 파라솔 둘이 그려졌다 → 구역 편집 ZI · ZJ 로 지움(배운 것 92). 그늘이 필요하면 차양 · 나무 그늘로.')
out = json.dumps(d, ensure_ascii=False, indent=1)
assert json.loads(out) == d
open(P, 'w', encoding='utf-8').write(out)
print('예약', len(R))
